/**
 * Contracts generated by standing with a named village.
 *
 * `mood` gates them: 'hostile' appears when relations have soured, 'warm' when
 * they have not. `{village}` is substituted with the real village name so the
 * board names the actual party — a sabotage job reads as a grievance against
 * someone specific, not a generic errand.
 */
export const DIPLOMATIC_MISSIONS = [
  { mood: 'hostile', n: 'Salt the Wells of {village}',   rk: 'B', ryo: 8000,  rep: 8,  dur: 2, risk: 0.34, mp: 62, sq: false, spec: 'stealth',
    flavour: 'Their reservoirs feed three districts. They will know it was deliberate; they will not be able to prove who.' },
  { mood: 'hostile', n: 'Discredit the {village} Envoy', rk: 'B', ryo: 7600,  rep: 9,  dur: 2, risk: 0.30, mp: 58, sq: false, spec: 'intel',
    flavour: 'A career ends in a single evening, if the right ledger reaches the right table.' },
  { mood: 'hostile', n: 'Break the {village} Border Post', rk: 'A', ryo: 13200, rep: 17, dur: 3, risk: 0.44, mp: 88, sq: true, spec: 'siege',
    flavour: 'They built it on ground that was never theirs. Time to make the point in daylight.' },
  { mood: 'warm',    n: 'Joint Patrol with {village}',   rk: 'C', ryo: 4200,  rep: 7,  dur: 1, risk: 0.14, mp: 34, sq: false, spec: 'combat',
    flavour: 'Their captain has worked with ours before. It goes easier when it is not a first meeting.' },
  { mood: 'warm',    n: 'Escort the {village} Delegation', rk: 'B', ryo: 6600, rep: 11, dur: 2, risk: 0.20, mp: 52, sq: false, spec: 'escort',
    flavour: 'Bring them home intact and the treaty signs itself.' },
  { mood: 'warm',    n: 'Relieve the {village} Garrison', rk: 'A', ryo: 12800, rep: 18, dur: 3, risk: 0.36, mp: 86, sq: true, spec: 'recovery',
    flavour: 'They asked. That they asked at all is the important part.' },
]

/** Relation thresholds at which each mood's contracts become available. */
export const HOSTILE_BELOW = 30
export const WARM_ABOVE = 70

/** Signature contracts for an element. Empty for an unknown element. */
export function signatureMissionsFor(element) {
  return SIGNATURE_MISSIONS.filter(m => m.el === element)
}

/** 'hostile' | 'warm' | null for a relation value. */
export function moodFor(rel) {
  const r = rel ?? 50
  if (r < HOSTILE_BELOW) return 'hostile'
  if (r > WARM_ABOVE) return 'warm'
  return null
}

/**
 * Diplomatic contracts available against one village, with `{village}`
 * substituted. Returns [] when relations are unremarkable — most of the time
 * nothing should be on offer, or the board fills with grievances.
 */
export function diplomaticMissionsFor(village) {
  const mood = moodFor(village?.rel)
  if (!mood || !village?.n) return []
  return DIPLOMATIC_MISSIONS
    .filter(m => m.mood === mood)
    .map(m => ({ ...m, n: m.n.replace('{village}', village.n), village: village.n }))
}
